const labels={queued:'排队中',running:'进行中',complete:'已完成',failed:'失败',cancelled:'已取消',needs_review:'待校验'};
const kinds={arrangement:'配器与鼓伴奏',expression:'演奏表情',metadata:'标题与封面',pdf:'PDF 预览',transcription:'音视频转录',photos:'照片整理与识谱',ai:'AI 指令'};
function naturalDetail(item){
 const detail=String(item.detail||item.error||labels[item.status]||item.status||'');
 if(item.status==='failed'&&item.kind==='ai')return '未完成：'+detail;
 if(item.status==='failed')return `处理失败：${detail}。任务已停止，其他后台任务不会受影响；可以点击“重试”重新处理。`;
 if(item.status==='needs_review')return `需要你的选择：${detail}。选择后任务会从当前阶段继续。`;
 if(item.status==='queued')return detail==='等待空闲处理'?`正在等待后台资源：${kinds[item.kind]||item.kind||'任务'}尚未开始，队列会自动继续。`:detail;
 if(item.status==='running'&&item.kind==='ai')return detail;
 if(item.status==='failed'&&item.kind==='ai')return '未完成：'+detail;
 if(item.status==='running')return `当前步骤：${detail}。后台正在处理，页面操作不会中断此任务。`;
 return detail;
}
const groupOpen={ai:false,queue:false};
const tasks=new Map();let panel,list,summary,lastDraw='',foreground={},polling=true,lastPollError='';const visualProgress=new Map();
function smoothProgress(bar,id,target){const start=visualProgress.get(id)??0,from=Math.min(start,target),direction=target>=start?1:-1,started=performance.now(),duration=Math.max(180,Math.abs(target-start)*10);function frame(now){const value=from+Math.min(1,(now-started)/duration)*Math.abs(target-start);const next=direction>0?value:Math.max(0,start-(value-from));bar.value=next;visualProgress.set(id,next);if(Math.abs(next-target)>.05)requestAnimationFrame(frame);else{bar.value=target;visualProgress.set(id,target);}}requestAnimationFrame(frame);}
function init(){if(panel){if(!panel.isConnected){const target=document.querySelector('#workspace-tasks')||document.querySelector('.score-library')?.parentElement;if(target)target.append(panel);}return;}panel=document.createElement('details');panel.className='task-center';panel.open=true;summary=document.createElement('summary');summary.textContent='任务中心';list=document.createElement('div');list.className='task-list';list.setAttribute('aria-live','polite');panel.append(summary,list);const target=document.querySelector('#workspace-tasks');if(target)target.append(panel);else document.querySelector('.score-library')?.after(panel);}
function draw(){
 init();const rank={running:0,queued:1,failed:2,needs_review:2,complete:3,cancelled:4};
 const ordered=[...tasks.values()].sort((a,b)=>(rank[a.status]??4)-(rank[b.status]??4)||(a.priority??20)-(b.priority??20)||b.created-a.created);const items=[...ordered.filter(x=>x.kind==='ai').slice(0,20),...ordered.filter(x=>x.kind!=='ai').slice(0,60)];
 const signature=JSON.stringify([items,foreground]);if(signature===lastDraw)return;lastDraw=signature;
 summary.textContent='任务中心';list.replaceChildren();if(!items.length){list.textContent=polling?'正在同步任务记录…':lastPollError?'任务暂时无法载入，正在重试：'+lastPollError:'暂无任务';return;}
 const active=items.find(item=>item.status==='running')||items.find(item=>item.status==='queued');
 if(active||foreground?.owner){const resource=document.createElement('p');resource.className='task-resource';const owner=foreground?.owner?'前台操作不会暂停后台队列':'后台队列空闲，准备开始';resource.textContent=active?`当前任务：${active.scoreTitle||active.label||'未命名曲谱'} · ${({arrangement:'配器与鼓伴奏',expression:'演奏表情',metadata:'标题与封面',pdf:'PDF 预览',transcription:'音视频转录',photos:'照片整理与识谱',ai:'AI 指令'})[active.kind]||'音符识别'}。${active.status==='running'?'正在处理。':'已排队，后台将继续运行。'}`:owner;list.append(resource);}
 const containers={};for(const [key,label]of [['ai','AI 任务'],['queue','处理队列']]){
  const subset=items.filter(item=>(item.kind==='ai')===(key==='ai'));const group=document.createElement('section');group.className='task-group';group.classList.toggle('is-expanded',groupOpen[key]);const toggle=document.createElement('button');toggle.type='button';toggle.className='task-group-toggle';toggle.setAttribute('aria-expanded',String(groupOpen[key]));const name=document.createElement('span');name.textContent=label;const count=document.createElement('small');count.textContent=String(subset.length);toggle.append(name,count);const fold=document.createElement('div');fold.className='task-group-fold';const body=document.createElement('div');body.className='task-group-items';body.inert=!groupOpen[key];fold.append(body);group.append(toggle,fold);list.append(group);containers[key]=body;toggle.onclick=()=>{groupOpen[key]=!groupOpen[key];toggle.setAttribute('aria-expanded',String(groupOpen[key]));group.classList.toggle('is-expanded',groupOpen[key]);body.inert=!groupOpen[key];if(groupOpen[key]){group.classList.add('is-unfurling');setTimeout(()=>group.classList.remove('is-unfurling'),1100);}};
 }
 for(const item of items){
  const row=document.createElement('div');row.className='task-row';row.dataset.status=item.status;
  const title=document.createElement('strong');title.textContent=item.scoreTitle||item.label||('曲谱 '+(item.digest||'').slice(0,8));
  const state=document.createElement('span');state.className='task-detail';state.textContent=naturalDetail(item);state.title=state.textContent;
  const kind=document.createElement('small');kind.textContent=({arrangement:'配器与鼓伴奏',expression:'演奏表情',metadata:'标题与封面',pdf:'PDF 预览',transcription:'音视频转录',photos:'照片整理与识谱',ai:'AI 指令'})[item.kind]||item.label||'音符识别';
  const waiting=item.status==='queued'&&(!Number.isFinite(item.progress)||Number(item.progress)<=0);const percent=document.createElement('b');percent.className='task-percent';percent.textContent=waiting?'等待':Number.isFinite(item.progress)?Math.round(Math.max(0,Math.min(100,item.progress)))+'%':'等待';
  row.append(title,kind,percent,state);if(!waiting){const bar=document.createElement('progress');bar.max=100;bar.value=visualProgress.get(item.id)??0;bar.setAttribute('aria-label',title.textContent+' '+kind.textContent);row.append(bar);smoothProgress(bar,item.id,Number(item.progress)||0);}
  if(item.kind==='transcription'&&item.status==='needs_review'){
   for(const [choice,label] of [['separate','分离钢琴后转录'],['original','直接转录原音频']]){
    const button=document.createElement('button');button.className='small-button';button.textContent=label;
    button.onclick=async()=>{button.disabled=true;try{const r=await fetch('/api/media/choice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({digest:item.digest,choice})});if(!r.ok)throw Error('提交失败，请重试');reportTask(item.id,{status:'cancelled',detail:'已选择转录方式，新任务已排队'});}catch(e){state.textContent=e.message;button.disabled=false;}};row.append(button);
   }
  }
  const action=document.createElement('button');action.className='small-button';
  if(item.status==='failed'&&item.kind&&item.jobId){action.textContent='重试';action.onclick=async()=>{action.disabled=true;try{const response=await fetch('/api/processing/retry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:item.jobId})});if(!response.ok)throw Error('重试失败');reportTask(item.id,{status:'queued',detail:'等待重试'});}catch(error){state.textContent=error.message;action.disabled=false;}};}
  else if(item.digest&&['queued','running'].includes(item.status)){action.textContent='查看曲谱';action.onclick=()=>document.dispatchEvent(new CustomEvent('task-open-score',{detail:item}));}
  else if(item.cancel&&['queued','running'].includes(item.status)){action.textContent='取消';action.onclick=item.cancel;}else action.hidden=true;
  row.append(action);
  if(item.jobId&&['arrangement','expression','metadata','pdf','transcription','photos'].includes(item.kind)&&['queued','failed','needs_review'].includes(item.status)){
   const first=document.createElement('button');first.className='small-button priority-button';first.textContent=item.status==='queued'?'优先处理':'优先重试';first.onclick=async()=>{
    first.disabled=true;try{const response=await fetch('/api/processing/priority',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:item.jobId})});
     if(!response.ok)throw Error(response.status===404?'服务需要重启以启用任务排序':'任务状态已改变，请刷新重试');
     reportTask(item.id,{status:'queued',priority:Math.min(0,...items.map(t=>t.priority||0))-1,detail:'已设为下一项，当前任务完成后开始'});
    }catch(error){state.textContent=error.message;first.disabled=false;}
   };row.append(first);
  }
  if(item.kind==='ai'&&item.result){const resultBox=document.createElement('details');resultBox.className='ai-task-result';const heading=document.createElement('summary');heading.textContent='查看结果';const content=document.createElement('div');content.textContent=item.result;content.style.whiteSpace='pre-wrap';resultBox.append(heading,content);row.append(resultBox);}
  const container=containers[item.kind==='ai'?'ai':'queue'];row.style.setProperty('--row-order',container.children.length);container.append(row);
 }
}
export function reportTask(id,changes){const previous=tasks.get(id)||{id,created:Date.now(),status:'running'};tasks.set(id,{...previous,...changes});draw();return id;}
export function showTasks(){init();panel.open=true;document.dispatchEvent(new Event('show-task-center'));}
export function uploadWithProgress(file,id){return new Promise((resolve,reject)=>{let attempt=0,aborted=false;const send=()=>{const xhr=new XMLHttpRequest();attempt+=1;xhr.open('POST','/api/scores');xhr.timeout=15*60*1000;xhr.setRequestHeader('Content-Type','application/pdf');xhr.setRequestHeader('X-Score-Name',encodeURIComponent(file.name));reportTask(id,{label:file.name,status:'running',progress:0,detail:attempt>1?'上传连接已恢复，正在重试 0%':'上传 0%',cancel:()=>{aborted=true;xhr.abort();}});xhr.upload.onprogress=e=>{reportTask(id,{progress:e.lengthComputable?e.loaded/e.total*100:undefined,detail:e.lengthComputable?`上传第 ${attempt} 次 ${Math.round(e.loaded/e.total*100)}%`:'正在上传'});};xhr.onload=()=>{try{const data=JSON.parse(xhr.responseText);if(xhr.status<200||xhr.status>=300)throw Error(data.error||'上传失败');reportTask(id,{status:'complete',progress:100,digest:data.id,detail:'已上传，正在提交识谱'});resolve(data);}catch(e){reject(e);}};const retry=()=>{if(aborted)return reject(Error('上传已取消'));if(attempt<2){reportTask(id,{detail:'上传连接中断，正在自动重试（不会重复保存）'});setTimeout(send,700);return;}reject(Error('上传连接失败：服务端在接收 PDF 时连接中断。请保持页面打开后重试；若文件较大，请先压缩或拆分 PDF。'));};xhr.onerror=retry;xhr.ontimeout=()=>retry();xhr.onabort=()=>{if(!aborted)retry();};xhr.send(file);};send();});}
async function uploadChunked(file,id){const size=4*1024*1024,total=Math.ceil(file.size/size),uploadId=crypto.randomUUID();let result=null;for(let index=0;index<total;index++){const chunk=file.slice(index*size,Math.min(file.size,(index+1)*size));const response=await fetch('/api/scores/chunk',{method:'POST',headers:{'Content-Type':'application/pdf','X-Upload-Id':uploadId,'X-Chunk-Index':String(index),'X-Chunk-Total':String(total),'X-Score-Name':encodeURIComponent(file.name)},body:chunk});if(!response.ok)throw Error((await response.text())||'分块上传失败');result=await response.json();reportTask(id,{progress:(index+1)/total*100,detail:`分块上传 ${index+1} / ${total}`});}return result;}
async function preparePhoto(file){
 const bitmap=await createImageBitmap(file);const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));
 const src=document.createElement('canvas');src.width=Math.round(bitmap.width*scale);src.height=Math.round(bitmap.height*scale);const c=src.getContext('2d');c.drawImage(bitmap,0,0,src.width,src.height);const data=c.getImageData(0,0,src.width,src.height),w=src.width,h=src.height;let l=w,t=h,r=0,b=0;
 for(let y=0;y<h;y+=4)for(let x=0;x<w;x+=4){const byteIndex=(y*w+x)*4,lum=(data.data[byteIndex]+data.data[byteIndex+1]+data.data[byteIndex+2])/3;if(lum<242){l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);}}
 const pad=Math.round(Math.min(w,h)*.025);l=Math.max(0,l-pad);r=Math.min(w-1,r+pad);t=Math.max(0,t-pad);b=Math.min(h-1,b+pad);const crop=document.createElement('canvas');crop.width=r-l+1;crop.height=b-t+1;crop.getContext('2d').drawImage(src,l,t,crop.width,crop.height,0,0,crop.width,crop.height);
 let final=crop;if(crop.width>crop.height){final=document.createElement('canvas');final.width=crop.height;final.height=crop.width;const f=final.getContext('2d');f.translate(final.width/2,final.height/2);f.rotate(Math.PI/2);f.drawImage(crop,-crop.width/2,-crop.height/2);}
 const jpeg=await new Promise(res=>final.toBlob(res,'image/jpeg',.92));const bytes=new Uint8Array(await jpeg.arrayBuffer());const enc=new TextEncoder(),parts=[];const add=s=>{const b=enc.encode(s);parts.push(b);return parts.reduce((n,x)=>n+x.length,0)-b.length};let pdf='%PDF-1.4\n',offs=[0];const bin=String.fromCharCode(...bytes);pdf+='1 0 obj<< /Type /Catalog /Pages 2 0 R>>endobj\n2 0 obj<< /Type /Pages /Kids [3 0 R] /Count 1>>endobj\n3 0 obj<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im 4 0 R>> /ProcSet [/PDF /ImageC]>> /Contents 5 0 R>>endobj\n';offs.push(pdf.length);pdf+=`4 0 obj<< /Type /XObject /Subtype /Image /Width ${final.width} /Height ${final.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${bytes.length}>>stream\n${bin}\nendstream endobj\n`;const stream='q 595 0 0 842 0 0 cm /Im Do Q';offs.push(pdf.length);pdf+=`5 0 obj<< /Length ${stream.length}>>stream\n${stream}\nendstream endobj\n`;const xref=pdf.length;pdf+='xref\n0 6\n0000000000 65535 f \n';for(let objectIndex=1;objectIndex<6;objectIndex++)pdf+=String(offs[objectIndex]||0).padStart(10,'0')+' 00000 n \n';pdf+=`trailer<< /Size 6 /Root 1 0 R>>\nstartxref\n${xref}\n%%EOF`;return new File([pdf,bytes],file.name.replace(/\.[^.]+$/i,'.pdf'),{type:'application/pdf'});
}
function uploadImage(file,id){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/scores/image');xhr.setRequestHeader('Content-Type',file.type||'image/jpeg');xhr.setRequestHeader('X-Score-Name',encodeURIComponent(file.name));xhr.upload.onprogress=e=>{if(e.lengthComputable)reportTask(id,{progress:e.loaded/e.total*100,detail:`上传并扫描 ${Math.round(e.loaded/e.total*100)}%`});};xhr.onload=()=>{try{const data=JSON.parse(xhr.responseText);if(xhr.status<200||xhr.status>=300)throw Error(data.error||'图片扫描失败');resolve(data);}catch(error){reject(error);}};xhr.onerror=()=>reject(Error('图片上传连接失败'));xhr.send(file);});}
let uploading=Promise.resolve();
export function enqueueUploads(files,onUploaded){showTasks();for(const file of files){const id='upload-'+Date.now()+'-'+Math.random().toString(36).slice(2);let cancelled=false;reportTask(id,{label:file.name,status:'queued',progress:0,cancel:()=>{cancelled=true;reportTask(id,{status:'cancelled',detail:'已取消'});}});uploading=uploading.then(async()=>{if(cancelled)return;try{if(file.size>20*1024*1024)throw Error('文件超过 20 MB');const signature=new TextDecoder().decode(await file.slice(0,1024).arrayBuffer());let saved;if(!signature.includes('%PDF-')){if(!/^image\//i.test(file.type))throw Error('请选择 PDF 或谱面图片');reportTask(id,{detail:'正在裁切纸面、校正方向并生成扫描件'});saved=await uploadImage(file,id);}else saved=await uploadWithProgress(file,id);const response=await fetch(`/api/scores/${saved.id}/recognize`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const job=await response.json();if(!response.ok)throw Error(job.error||'提交识谱失败');reportTask(id,{detail:job.cached?'已复用云端识谱结果':'上传完成，已加入识谱队列'});await onUploaded?.({...saved,jobId:job.id,status:job.status,hasPdf:true,title:'正在校对标题'});}catch(e){reportTask(id,{status:e.message.includes('取消')?'cancelled':'failed',detail:e.message});}});}}
async function poll(){polling=true;try{const saved=await fetch('/api/ai-tasks',{signal:AbortSignal.timeout(20000)});if(saved.ok){for(const item of (await saved.json()).tasks||[]){const current=tasks.get(item.id);if(!current||!current.updated||item.updated>current.updated)tasks.set(item.id,item);}draw();}const response=await fetch('/api/tasks',{signal:AbortSignal.timeout(20000)});if(response.ok){const {tasks:remote,foreground:owner={}}=await response.json();foreground=owner||{};for(const item of remote){const stage=String(item.stage||'');const detail=item.error||(stage.includes('等待前台操作结束')?'后台继续处理':item.stage||item.detail||labels[item.status]);tasks.set('omr-'+item.id,{...item,id:'omr-'+item.id,jobId:item.id,created:item.created*1000,label:item.label||'音符识别',detail,progress:item.status==='complete'?100:item.progress});}draw();lastPollError='';polling=false;document.dispatchEvent(new CustomEvent('cloud-jobs-update',{detail:remote}));}}catch(error){polling=false;lastPollError=['AbortError','TimeoutError'].includes(error.name)?'服务响应超时':error.message||'连接失败';draw();}setTimeout(poll,2200);}
setTimeout(()=>{init();draw();poll();},0);
